const escapeVisual = s => String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const frame=(title,content)=>`<div class="visual"><div class="visual-head"><b>${title}</b><span>INTERACTIVE / 教学模型</span></div><div class="visual-body">${content}</div></div>`;
export function heroDiagram(){return `<svg viewBox="0 0 410 245" role="img" aria-labelledby="hero-diagram-title"><title id="hero-diagram-title">编译时将源码变为带 hook 的二进制，运行时产生与现有手动 Span 关联的调用树</title><defs><marker id="ha" markerWidth="6" markerHeight="6" refX="5" refY="3" orient="auto"><path d="M0 0L6 3L0 6" fill="none" stroke="#6b8263"/></marker></defs><g fill="none" stroke="#9db28b" stroke-width="1"><path d="M105 50H149M259 50H302M350 77V108H71V137" marker-end="url(#ha)"/><path d="M107 160H157M208 179V207H268" marker-end="url(#ha)"/><path d="M208 160H268" marker-end="url(#ha)"/></g><g font-family="monospace" font-size="11"><rect x="3" y="24" width="102" height="53" rx="4" fill="#f5f7ef" stroke="#b7c6a9"/><text x="54" y="47" text-anchor="middle" fill="#19372f">Go source</text><text x="54" y="63" text-anchor="middle" fill="#728369" font-size="9">业务 + 依赖</text><rect x="149" y="24" width="110" height="53" rx="4" fill="#19372f"/><text x="204" y="47" text-anchor="middle" fill="#d6eb91">otel build</text><text x="204" y="63" text-anchor="middle" fill="#bbcfad" font-size="9">匹配 → AST → hook</text><rect x="302" y="24" width="103" height="53" rx="4" fill="#f5f7ef" stroke="#b7c6a9"/><text x="353" y="47" text-anchor="middle" fill="#19372f">binary</text><text x="353" y="63" text-anchor="middle" fill="#728369" font-size="9">标准 Go 编译器</text><text x="4" y="104" fill="#6b8263" font-size="8" letter-spacing="2">COMPILE TIME</text><text x="4" y="127" fill="#6b8263" font-size="8" letter-spacing="2">RUNTIME</text><rect x="4" y="138" width="103" height="42" rx="4" fill="#19372f"/><text x="55" y="164" text-anchor="middle" fill="#d6eb91">server span</text><rect x="157" y="138" width="103" height="42" rx="4" fill="#f5f7ef" stroke="#b7c6a9"/><text x="208" y="164" text-anchor="middle" fill="#19372f">manual span</text><rect x="268" y="138" width="137" height="42" rx="4" fill="#d6eb91" stroke="#b7c6a9"/><text x="337" y="164" text-anchor="middle" fill="#19372f">Redis · auto span</text><rect x="268" y="190" width="137" height="38" rx="4" fill="#f5f7ef" stroke="#b7c6a9"/><text x="337" y="214" text-anchor="middle" fill="#19372f">HTTP · auto span</text></g></svg>`;}
const stages=[
['输入','模块与源码','先有一个能用普通 go build 编译的目标。固定 Go toolchain、依赖版本和工具提交；编译期探针不能凭空修复业务源码。','go env GOMOD GOTOOLCHAIN GOOS GOARCH'],
['预处理','规则 + 依赖','Preprocess 交替做依赖准备、规则筛选与刷新，准备 hook module 和注入依赖。实际实现不是“一次简单替换”。','tool/preprocess/preprocess.go → Preprocess'],
['工具代理','-toolexec','标准 go build 启动 compiler 等工具时，经 otel 的内部代理处理。代理识别编译动作，非插桩操作继续转发。','runBuildWithToolexec → go build -toolexec=…'],
['结构改写','AST / DST','找到命中的函数声明，将进入与退出跳转点写进编译输入。解析的是程序结构，不是全项目搜索替换字符串。','RuleProcessor.instrument → apply_func.go'],
['标准编译','compile / link','生成代码仍要满足 Go 类型检查与符号链接契约；hook 签名或 linkname 目标错误会暴露在这一层。','Go compiler → object files → linker'],
['运行时','hook → SDK','函数执行时，hook 用 CallContext 和 context 读参数、创建或结束 Span；SDK 决定记录、批处理与导出。','OnEnter → original function → OnExit'],
['观察结果','Trace / log','检查的不只是 TraceID：还包括 Span 数、scope、kind、父节点、采样和上报。页面模型不会执行你的 Go 代码。','SpanContext ≠ recorded Span ≠ exported Trace']];
function pipeline(){return frame('一次构建，两个时间维度',`<div data-v="pipeline"><div class="visual-controls"><button class="visual-btn" data-step="-1" aria-label="上一步">←</button><button class="visual-btn" data-step="1" aria-label="下一步">下一步 →</button><label>阶段 <input type="range" min="0" max="6" value="0" aria-label="编译流程阶段"></label><span class="mono" data-stage-count>01 / 07</span></div><div class="flow">${stages.map((s,i)=>`<button class="flow-node ${i===0?'active':''}" data-phase="${i}">${s[0]}<small>${s[1]}</small></button>${i<6?'<span class="flow-arrow" aria-hidden="true">→</span>':''}`).join('')}</div><div class="diagram-output" aria-live="polite"></div><p class="diagram-caption">点选任一节点。前五步发生在构建期；后两步需要实际运行二进制。节点为学习分层，不代表真实函数调用次数。</p></div>`);}
function context(){return frame('同一任务，父上下文从哪里来？',`<div data-v="context"><div class="visual-controls"><label>执行方式 <select data-mode><option value="direct">普通函数调用</option><option value="goroutine">新 goroutine</option><option value="worker">预先启动的 worker</option><option value="message">跨进程消息</option></select></label><label><input type="checkbox" data-pass checked>显式交接 context / carrier</label><label><input type="checkbox" data-auto>启用插桩继承模型</label></div><div class="trace-tree" aria-live="polite"></div><div class="diagram-output"></div><p class="diagram-caption">ID 为教学符号。新 goroutine 的 GLS 继承仅表示本课程版本的适用场景，不是 Go 原生保证；本模型不模拟 worker/message 的自动交接适配；具体库规则可能另有支持。跨消息模型假设双方配置相同传播器。</p></div>`);}
function propagation(){return frame('把 Trace ID 和父 Span ID 分开观察',`<div data-v="propagation"><div class="visual-controls"><label>输入格式 <select data-format><option value="multi">只有 B3 多头</option><option value="w3c">只有 W3C</option><option value="single">只有 B3 单头</option></select></label><label><input type="checkbox" data-w3c>网关启用 W3C 提取</label><label><input type="checkbox" data-normalize>统一更新转发头</label></div><div class="two-columns"><div><small class="figure-label">真实请求经过的路径</small><div class="trace-tree">上游 A\n  └─ 网关入口 B\n       └─ 网关出站 C\n            └─ 应用 D</div></div><div><small class="figure-label">后端可能展示的 Span 树</small><div class="trace-tree" data-tree aria-live="polite"></div></div></div><div class="diagram-output"></div><p class="diagram-caption">此模型复现案例中的优先级，不替所有网关实现作结论。“单头残留”需出站请求头证据；仅凭树形图能证明父节点错误，不能证明头的具体改写机制。</p></div>`);}
function rule(){return frame('先判断能否命中，再讨论能否兼容',`<div data-v="rule"><div class="visual-controls"><label>目标库版本 <input type="text" data-version value="1.25.12" inputmode="decimal" aria-label="目标库版本"></label><label>规则范围 <select data-range><option value="1.25.10">[1.22.0, 1.25.10)</option><option value="1.26.0">[1.22.0, 1.26.0)</option></select></label><label><input type="checkbox" data-signature>已用新版本验证签名和行为</label></div><div class="flow"><div class="flow-node">ImportPath<small>示例：gorm.io/gorm</small></div><span class="flow-arrow">→</span><div class="flow-node" data-version-node>版本条件</div><span class="flow-arrow">→</span><div class="flow-node">Function / receiver<small>结构匹配</small></div><span class="flow-arrow">→</span><div class="flow-node" data-compatible>兼容证明</div></div><div class="diagram-output" aria-live="polite"></div><p class="diagram-caption">教学匹配器只处理三段数字稳定版本，未模拟全部 semver、依赖条件和上游函数正则细节。区间右侧 “)” 表示不包含上界；扩大范围不是兼容证明。</p></div>`);}
function hook(){return frame('CallContext 改参数，究竟会发生什么？',`<div data-v="hook"><div class="visual-controls"><label>原始参数 <input type="number" value="2" data-input min="-100" max="100"></label><label><input type="checkbox" data-mutate>OnEnter 用 SetParam 改为 5</label><label><input type="checkbox" data-return>OnExit 用 SetReturnVal 改为 99</label></div><div class="flow"><div class="flow-node">caller<small data-caller>x = 2</small></div><span class="flow-arrow">→</span><div class="flow-node active">OnEnter<small data-enter>只读</small></div><span class="flow-arrow">→</span><div class="flow-node">原函数<small data-raw>double(x)</small></div><span class="flow-arrow">→</span><div class="flow-node active">OnExit<small data-exit>只读</small></div></div><div class="diagram-output" aria-live="polite"></div><p class="diagram-caption">这是正常返回路径的简化模型，不是上游生成代码逐字复刻。参数/返回值修改只用于学习实验；真实可观测探针应先保持业务语义。</p></div>`);}
function sampling(){return frame('有 Trace ID，为什么不一定查到 Trace？',`<div data-v="sampling"><div class="visual-controls"><label><input type="checkbox" data-parent checked>上游 sampled=1</label><label><input type="checkbox" data-export checked>exporter 与网络正常</label><label><input type="checkbox" data-tail checked>Collector 保留</label><label><input type="checkbox" data-query checked>租户 / 时间 / 入库正确</label></div><div class="flow"><div class="flow-node">SpanContext<small>TraceID = T</small></div><span class="flow-arrow">→</span><div class="flow-node" data-record>SDK 记录</div><span class="flow-arrow">→</span><div class="flow-node" data-send>导出 + 保留</div><span class="flow-arrow">→</span><div class="flow-node" data-find>查询可见</div></div><div class="diagram-output" aria-live="polite"></div><p class="diagram-caption">以已有远程父上下文、默认 ParentBased 子采样为例；实际 sampler/processor 可改变结果。开关表达因果条件，不是实时监控指标。</p></div>`);}
function coverage(){return frame('同一条 Trace 中，哪些 Span 应该存在？',`<div data-v="coverage"><div class="visual-controls"><label><input type="checkbox" data-existing checked>现有入口和 otelhttp 已启用</label><label><input type="checkbox" data-auto checked>自动探针启用</label><label><input type="checkbox" data-dedup checked>精确去重已验证</label></div><div class="trace-tree" aria-live="polite"></div><div class="diagram-output"></div><p class="diagram-caption">示意图把重复现象简化为相似节点；真实判断还需结合调用语义、scope、kind 与包裹关系。同一 TraceID 下的不同操作 Span 应保留。</p></div>`);}
export function renderVisual(kind){return ({pipeline,context,propagation,rule,hook,coverage,sampling,source:pipeline}[kind]||pipeline)();}
export function bindVisual(root){root.querySelectorAll('[data-v]').forEach(el=>{
 const $=s=>el.querySelector(s), checked=s=>$(s).checked;
 function update(){switch(el.dataset.v){
 case 'pipeline':{const i=Number($('input').value),s=stages[i];el.querySelectorAll('[data-phase]').forEach(n=>{n.classList.toggle('active',Number(n.dataset.phase)===i);n.setAttribute('aria-pressed',String(Number(n.dataset.phase)===i));});$('[data-stage-count]').textContent=`${String(i+1).padStart(2,'0')} / 07`;$('[data-step="-1"]').disabled=i===0;$('[data-step="1"]').disabled=i===6;$('.diagram-output').innerHTML=`<b>${s[0]} · ${s[1]}</b><br>${s[2]}<br><code>${escapeVisual(s[3])}</code>`;break;}
 case 'context':{const m=$('[data-mode]').value,pass=checked('[data-pass]'),auto=checked('[data-auto]'),linked=pass||(auto&&m==='goroutine');const names={direct:'普通调用',goroutine:'新协程',worker:'worker 任务',message:'消费任务'};$('.trace-tree').textContent=linked?`请求入口 · Trace T / Span A\n  └─ 手动业务 · Trace T / Span B\n       └─ ${names[m]} · Trace T / parent B`:`请求入口 · Trace T / Span A\n  └─ 手动业务 · Trace T / Span B\n\n${names[m]} · 新 Trace U / 无父节点`;
 $('.diagram-output').textContent=pass?(m==='message'?'发送方 Inject → 消息 carrier → 消费方 Extract，再创建消费 Span。网络不传 Go context 对象。':'把请求 ctx 交给执行函数，子 Span 沿用 Trace T，并以 B 为父节点。'):linked?'插桩通过适用的 runtime/OTel hook，把新协程连接到当前请求；显式 context 仍更容易审计。':m==='worker'?'worker 创建于请求之前。任务提交处没有 ctx 时，创建时继承无法识别任务来自哪个请求。':m==='message'?'没有 carrier，消费者不知道生产请求。两端都创建 Span 也无法恢复因果。':'使用 Background 开启子操作，没有请求父上下文。原生 Go 不会自动补齐。';break;}
 case 'propagation':{const f=$('[data-format]').value,w=checked('[data-w3c]'),n=checked('[data-normalize]');let tree,msg;if(f==='w3c'&&!w){tree='原始 Trace T\n上游 A\n\n新 Trace U\n网关入口 B → 出站 C → 应用 D';msg='网关未提取 W3C，先开启新 Trace U；下游接收到网关的 B3 上下文。响应 ID 可与应用日志一致，但与原始上游不同。';}else if(f==='single'&&!n){tree='Trace T\n上游 A\n  ├─ 网关入口 B → 出站 C\n  └─ 应用 D（parent = A）';msg='模拟旧 b3 单头仍指向 A、新多头指向 C。应用提取器优先单头，TraceID 相同但 parent 错误。请求仍实际经过网关。';}else{tree='Trace T\n上游 A\n  └─ 网关入口 B\n       └─ 出站 C\n            └─ 应用 D';msg='传入 ID 被沿用，转发上下文指向网关出站 C，应用父子关系正确。W3C 提取与出站更新必须各自成立。';}$('[data-tree]').textContent=tree;$('.diagram-output').textContent=msg;break;}
 case 'rule':{const val=$('[data-version]').value.trim(),parts=val.split('.'),valid=parts.length===3&&parts.every(x=>/^\d+$/.test(x));const cmp=(a,b)=>{for(let i=0;i<3;i++){if(+a[i]!==+b[i])return +a[i]-+b[i];}return 0;};const hit=valid&&cmp(parts,[1,22,0])>=0&&cmp(parts,$('[data-range]').value.split('.'))<0,proof=checked('[data-signature]');$('[data-version-node]').classList.toggle('active',hit);$('[data-compatible]').classList.toggle('active',hit&&proof);$('.diagram-output').textContent=!valid?'请输入三段数字版本，例如 1.25.12。':!hit?'版本不命中：这一条规则不会因扩大函数名正则而自动支持该版本。':!proof?'版本已命中，但兼容性仍未知。先核对 receiver、参数/返回值、私有字段和运行语义，再跑新旧版本 fixture。':'版本条件和“已验证”开关都满足。这只是学习状态：真实发布必须保存编译、运行与回归证据。';break;}
 case 'hook':{const x=Number($('[data-input]').value),m=checked('[data-mutate]'),r=checked('[data-return]'),arg=m?5:x,raw=arg*2;$('[data-caller]').textContent=`x = ${x}`;$('[data-enter]').textContent=m?'SetParam(0, 5)':'只读参数';$('[data-raw]').textContent=`${arg} × 2 = ${raw}`;$('[data-exit]').textContent=r?'SetReturnVal(0, 99)':'只读结果';$('.diagram-output').textContent=`调用者收到：${r?99:raw}。${m||r?'hook 改变了业务可观察结果；这说明 CallContext 有行为干预能力，探针必须有边界。':'只读 hook 保留原函数结果；新增遥测时先以此为验收基线。'}`;break;}
 case 'sampling':{const rec=checked('[data-parent]'),send=rec&&checked('[data-export]')&&checked('[data-tail]'),find=send&&checked('[data-query]');$('[data-record]').classList.toggle('active',rec);$('[data-send]').classList.toggle('active',send);$('[data-find]').classList.toggle('active',find);$('.diagram-output').textContent=find?'本模型所有条件满足：Trace T 可在正确后端被查到。':!rec?'上下文中仍有 Trace T，但默认 ParentBased 尊重未采样父节点，不导出这个子 Span。日志可以继续写 TraceID。':!send?'SDK 已记录，不代表最终保存成功。检查 exporter、网络、队列、Collector 策略。':'数据可能已保存，但时间范围、租户或入库延迟使查询暂不可见；先核对查询条件。';break;}
 case 'coverage':{const old=checked('[data-existing]'),auto=checked('[data-auto]'),dedup=checked('[data-dedup]');const lines=['Trace T'];if(old)lines.push('└─ 已有 server Span A');if(auto&&(!old||!dedup))lines.push(`${old?'   └─':'└─'} 自动 server Span ${old?'A2（可能重复）':'A'}`);if(old||auto)lines.push('   └─ 手动业务 Span B');if(old)lines.push('       ├─ 已有 otelhttp client Span C');if(auto&&(!old||!dedup))lines.push(`       ├─ 自动 HTTP client ${old?'C2（可能重复）':'C'}`);if(auto)lines.push('       └─ 自动 Redis Span D');$('.trace-tree').textContent=lines.join('\n');$('.diagram-output').textContent=old&&auto&&!dedup?'同一入口或同一 HTTP 操作可能被两次包装。不能因为已有任意 Span 就跳过所有自动子调用；应识别同一操作的已有埋点。':old&&auto?'已有入口、已有 HTTP 埋点保留；自动规则补充未覆盖的 Redis 调用。精确去重仍需实际 wrapper 路径证明。':!old&&!auto?'没有入口埋点；手动 Span 也可能缺少父上下文。':'查看每个节点的来源。增加 Span 的目标是解释真实操作，既不是越多越好，也不是越少越好。';break;}
 }}
 el.addEventListener('change',update);el.addEventListener('input',update);el.addEventListener('click',e=>{const phase=e.target.closest('[data-phase]'),step=e.target.closest('[data-step]');if(phase)$('input').value=phase.dataset.phase;if(step)$('input').value=Math.max(0,Math.min(6,Number($('input').value)+Number(step.dataset.step)));if(phase||step)update();});update();
 });}
